import{_ as r,a0 as s,w as m,s as a,ao as o,I as p,x as e,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse(`{"title":"如何使用xkill命令杀掉Linux进程/未响应的程序 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用xkill命令杀掉Linux进程/未响应的程序 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用xkill命令杀掉Linux进程/未响应的程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用xkill命令杀掉Linux进程/未响应的程序 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150527 How to Kill Linux Processes or Unresponsive Applications Using 'xkill' Command","title":"如何使用xkill命令杀掉Linux进程/未响应的程序","tag":"201506","desc":""},"relativePath":"201506/20150527 How to Kill Linux Processes or Unresponsive Applications Using 'xkill' Command.md","filePath":"[post].md"}`),d={name:"201506/20150527 How to Kill Linux Processes or Unresponsive Applications Using 'xkill' Command.md"};function x(u,l,k,g,f,w){const i=s("Link");return m(),a("div",null,[l[16]||(l[16]=o(`<h1 id="如何使用xkill命令杀掉linux进程-未响应的程序" tabindex="-1">如何使用xkill命令杀掉Linux进程/未响应的程序 <a class="header-anchor" href="#如何使用xkill命令杀掉linux进程-未响应的程序" aria-label="Permalink to “如何使用xkill命令杀掉Linux进程/未响应的程序”">​</a></h1><p>我们如何在Linux中杀掉一个资源/进程？很明显我们会找出资源的pid然后用kill命令。</p><p>说的更明白一点，我们可以找到某个资源（比如terminal）的PID：</p><pre><code>$ ps -A | grep -i terminal

6228 ?        00:00:00 gnome-terminal
</code></pre><p>上面的输出中，‘6288’就是进程（gnome-terminal）的pid， 使用下面的命令来杀掉进程。</p><pre><code>$ kill 6228
</code></pre><p>kill命令会发送一个信号给该pid的进程。</p><p>另外一个方法是我们可以使用pkill命令，它可以基于进程的名字或者其他的属性来杀掉进程。同样我们要杀掉一个叫terminal的进程可以这么做：</p><pre><code>$ pkill terminal
</code></pre><p><strong>注意</strong>: pkill命令后面进程名的长度不大于15个字符</p><p>pkill看上去更加容易上手，因为你你不用找出进程的pid。但是如果你要对系统做更好的控制，那么没有什么可以打败&#39;kill&#39;。使用kill命令可以更好地审视你要杀掉的进程。</p>`,11)),p("p",null,[l[1]||(l[1]=e("我们已经有一篇覆盖了",-1)),t(i,{href:"https://linux.cn/article-2116-1.html"},{default:n(()=>[...l[0]||(l[0]=[e("kill、pkill和killall命令",-1)])]),_:1}),l[2]||(l[2]=e("细节的指导了。",-1))]),l[17]||(l[17]=o(`<p>对于那些运行X Server的人而言，有另外一个工具称为xkill可以将进程从X Window中杀掉而不必传递它的名字或者pid。</p><p>xkill工具强制X server关闭与它的客户程序之间的联系，其结果就是X resource关闭了这个客户程序。xkill是X11工具集中一个非常容易上手的杀掉无用窗口的工具。</p><p>它支持的选项如在同时运行多个X Server时使用-display选项后面跟上显示号连接到指定的X server，使用-all(并不建议)杀掉所有在屏幕上的所有顶层窗口，以及帧（-frame）参数。</p><p>要列出所有的客户程序你可以运行：</p><pre><code>$ xlsclients
</code></pre><h4 id="示例输出" tabindex="-1">示例输出 <a class="header-anchor" href="#示例输出" aria-label="Permalink to “示例输出”">​</a></h4><pre><code>&#39;  &#39; /usr/lib/libreoffice/program/soffice
deb  gnome-shell
deb  Docky
deb  google-chrome-stable
deb  soffice
deb  gnome-settings-daemon
deb  gnome-terminal-server
</code></pre><p>如果后面没有跟上资源id，xkill会将鼠标指针变成一个特殊符号，类似于“X”。只需在你要杀掉的窗口上点击，它就会杀掉它与server端的通信，这个程序就被杀掉了。</p><pre><code>$ xkill
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Xkill.png" alt="Xkill Command"></p><p><em>使用xkill杀掉进程</em></p><p>需要注意的是xkill并不能保证它的通信会被成功杀掉/退出。大多数程序会在与服务端的通信被关闭后杀掉。然而仍有少部分会继续运行。</p><p>需要指出的点是：</p><ul><li>这个工具只能在X11 server运行的时候才能使用，因为这是X11工具的一部分。</li><li>不要在你杀掉一个资源而它没有完全退出时而困惑。</li><li>这不是kill的替代品</li></ul><p><strong>我需要在linux命令行中使用xkill么</strong></p><p>不是，你不必非在命令行中运行xkill。你可以设置一个快捷键，并用它来调用xkill。</p><p>下面是如何在典型的gnome3桌面中设置键盘快捷键。</p><p>进入设置-&gt; 选择键盘。点击&#39;+&#39;并添加一个名字和命令。点击点击新条目并按下你想要的组合键。我的是Ctrl+Alt+Shift+x。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/22.png" alt="Gnome Settings"></p><p><em>Gnome 设置</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/31.png" alt="Add Shortcut Key"></p><p><em>添加快捷键</em></p><p>下次你要杀掉一个X资源只要用组合键就行了（Ctrl+Alt+Shift+x），你看到你的鼠标变成x了。点击想要杀掉的x资源就行了。</p><hr>`,24)),p("p",null,[l[4]||(l[4]=e("via: ",-1)),t(i,{href:"http://www.tecmint.com/kill-processes-unresponsive-programs-in-ubuntu/"},{default:n(()=>[...l[3]||(l[3]=[e("http://www.tecmint.com/kill-processes-unresponsive-programs-in-ubuntu/",-1)])]),_:1})]),p("p",null,[l[8]||(l[8]=e("作者：",-1)),t(i,{href:"http://www.tecmint.com/author/avishek/"},{default:n(()=>[...l[5]||(l[5]=[e("Avishek Kumar",-1)])]),_:1}),l[9]||(l[9]=e(" 译者：",-1)),t(i,{href:"https://github.com/geekpi"},{default:n(()=>[...l[6]||(l[6]=[e("geekpi",-1)])]),_:1}),l[10]||(l[10]=e(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...l[7]||(l[7]=[e("wxy",-1)])]),_:1})]),p("p",null,[l[13]||(l[13]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[11]||(l[11]=[e("LCTT",-1)])]),_:1}),l[14]||(l[14]=e(" 原创翻译，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...l[12]||(l[12]=[e("Linux中国",-1)])]),_:1}),l[15]||(l[15]=e(" 荣誉推出",-1))])])}const _=r(d,[["render",x]]);export{L as __pageData,_ as default};
